/**
 * Bulk-safe handler for ContactTrigger.
 *
 * The trigger itself contains no SOQL or DML; all logic is delegated here.
 *
 * Budget per transaction (before + after contexts combined):
 *   - Insert of up to 200 Contacts: 2 SOQL queries, 1 DML statement.
 *   - Update of up to 200 Contacts:  1 SOQL query,  0 DML statements.
 */
public class ContactTriggerHandler {

    /**
     * BEFORE INSERT / BEFORE UPDATE
     * Defaults MailingCountry from the parent Account's BillingCountry and,
     * on insert only, LeadSource from the Account's AccountSource.
     * Uses a single SOQL query for all parent Accounts in the batch.
     */
    private static void populateFieldsFromAccounts(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public static void beforeInsert(List<Contact> newContacts) {
        populateFieldsFromAccounts(newContacts, true);
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        populateFieldsFromAccounts(newContacts, false);
    }

    /**
     * AFTER INSERT
     * If a new Contact has a Phone and its parent Account has a blank Phone,
     * copy the Contact's Phone onto the Account.
     *
     * Bulk-safe behaviour: one SOQL query for all candidate Accounts and a
     * single DML statement for all Accounts that need updating.
     *
     * Tie-break detail (matching the legacy trigger): when several new
     * Contacts of the same Account have a Phone and the Account has none,
     * the FIRST such Contact in trigger order sets the Account's Phone.
     * Because all Contacts for a given Account share the same Account
     * sObject instance in the map, once the first Contact sets a.Phone,
     * the blank-check fails for subsequent Contacts of that Account.
     */
    public static void afterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
