```apex
/**
 * Queueable job that re-rates Account records from AnnualRevenue.
 *
 * Each link in the chain processes at most 200 accounts using exactly one
 * SOQL query and one DML statement, then enqueues the remaining Ids as the
 * next link. Chaining is unconditional: chained queueable jobs also run in
 * test context (synchronously after Test.stopTest()), so the full chain is
 * verifiable in a single Apex test even for very large Id lists.
 */
public class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private List<Id> pendingAccountIds;

    /**
     * Primary constructor per spec. A null list is accepted and results in a
     * job that simply does nothing when executed.
     *
     * The list is stored by reference (not copied) to keep heap usage low
     * when very large lists (up to 50,000 Ids) are processed.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.pendingAccountIds = accountIds == null ? new List<Id>() : accountIds;
    }

    /** No-arg constructor: yields a job that does nothing when executed. */
    public AccountScoringJob() {
        this.pendingAccountIds = new List<Id>();
    }

    /**
     * Enqueues the first link of the chain and returns its job Id.
     * A null or empty list enqueues nothing and returns null.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        // Nothing to do (also covers execute(null) on a job with no Ids).
        if (pendingAccountIds == null || pendingAccountIds.isEmpty()) {
            return;
        }

        Integer total = pendingAccountIds.size();

        // First 200 Ids of this list.
        List<Id> chunk = total > BATCH_SIZE
            ? new List<Id>(pendingAccountIds.subList(0, BATCH_SIZE))
            : pendingAccountIds;

        // Everything after the first 200 Ids.
        List<Id> remaining = new List<Id>();
        for (Integer i = BATCH_SIZE; i < total; i++) {
            remaining.add(pendingAccountIds[i]);
        }

        // Consume the state so a direct or repeated invocation of execute()
        // cannot reprocess the same Ids.
        pendingAccountIds = null;

        // One SOQL query per execution. Ids that no longer exist (or null
        // Ids) simply return no rows.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :chunk
        ];

        for (Account acct : accounts) {
            acct.Rating = ratingFor(acct.AnnualRevenue);
        }

        // One DML statement per execution. Partial-success mode keeps the
        // chain alive: one bad record cannot roll back the whole chunk and
        // prevent the remaining accounts from being processed.
        if (!accounts.isEmpty()) {
            Database.update(accounts, false);
        }

        // Chain the remaining work. This runs in test context as well
        // (never skipped), so the entire chain executes after Test.stopTest().
        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    /**
     * AnnualRevenue of 1,000,000 or more => Hot.
     * AnnualRevenue of 100,000 or more  => Warm.
     * Anything else (including blank)    => Cold.
     */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= HOT_THRESHOLD) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= WARM_THRESHOLD) {
            return 'Warm';
        }
        return 'Cold';
    }
}
```

Key design notes:

- **Chaining is unconditional** — no `Test.isRunningTest()` bypass. Since Spring '21, chained Queueable jobs execute in test context after `Test.stopTest()`, so the full 250-job chain for 50,000 Ids completes and is verifiable in a single test, even in a Developer Edition scratch org.
- **Exactly 200 accounts per link** — one SOQL query (`WHERE Id IN :chunk`) and one DML statement (`Database.update`, partial success so a single failing record can't break the chain); the remainder is enqueued as the next link.
- **Null-safe everywhere** — `start(null)`/`start([]` returns `null` without enqueueing; `execute(null)` on a job instance (including one constructed with a null/empty list) returns without any SOQL, DML, or enqueue.
- **Heap-friendly** — the constructor stores the incoming list by reference and `execute` builds only one new "remaining" list, avoiding duplicate copies of a 50,000-element list.
- **State is consumed** in `execute` so a direct/repeated invocation cannot reprocess the same Ids.

