@IsTest
private class OpportunityCleanupServiceTest {

    /**
     * Builds an in-memory Opportunity (no DML, no SOQL) with a fake Id from
     * fflib_IDGenerator so nothing in this test class touches the database.
     */
    private static Opportunity makeOpportunity(Id id, String stageName, Date closeDate) {
        return new Opportunity(
            Id = id,
            Name = 'Opportunity ' + id,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    private static Id fakeOpportunityId() {
        return fflib_IDGenerator.generate(Opportunity.SObjectType);
    }

    @IsTest
    static void closesOnlyStaleOpportunitiesAndCommitsWorkExactlyOnce() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Date cutoff = Date.today();

        Id staleOpenId = fakeOpportunityId();
        Id staleOpenId2 = fakeOpportunityId();
        Id staleNullStageId = fakeOpportunityId();
        Id onCutoffId = fakeOpportunityId();
        Id afterCutoffId = fakeOpportunityId();
        Id closedWonId = fakeOpportunityId();
        Id closedLostId = fakeOpportunityId();
        Id nullCloseDateId = fakeOpportunityId();

        // Stale: open stage, CloseDate strictly before the cutoff.
        Opportunity staleOpen = makeOpportunity(staleOpenId, 'Prospecting', cutoff - 1);
        Opportunity staleOpen2 = makeOpportunity(staleOpenId2, 'Qualification', cutoff - 60);
        Opportunity staleNullStage = makeOpportunity(staleNullStageId, null, cutoff - 1);

        // Not stale: open stage but CloseDate on/after the cutoff.
        Opportunity onCutoff = makeOpportunity(onCutoffId, 'Prospecting', cutoff);
        Opportunity afterCutoff = makeOpportunity(afterCutoffId, 'Prospecting', cutoff + 30);

        // Not stale: closed stage, even though CloseDate is before the cutoff.
        Opportunity closedWon = makeOpportunity(closedWonId, 'Closed Won', cutoff - 1);
        Opportunity closedLost = makeOpportunity(closedLostId, 'Closed Lost', cutoff - 1);

        // Not stale: null CloseDate is not strictly before the cutoff.
        Opportunity nullCloseDate = makeOpportunity(nullCloseDateId, 'Prospecting', null);

        Set<Id> requestedIds = new Set<Id>{
            staleOpenId,
            staleOpenId2,
            staleNullStageId,
            onCutoffId,
            afterCutoffId,
            closedWonId,
            closedLostId,
            nullCloseDateId
        };

        mocks.when(selectorMock.selectById(requestedIds)).thenReturn(new List<Opportunity>{
            staleOpen,
            staleOpen2,
            staleNullStage,
            onCutoff,
            afterCutoff,
            closedWon,
            closedLost,
            nullCloseDate
        });

        Integer closedCount = OpportunityCleanupService.closeStale(requestedIds, cutoff);

        // The method returns the number of opportunities it closed.
        System.assertEquals(3, closedCount, 'should return the number of opportunities closed');

        // Each stale opportunity is closed with the lost reason.
        System.assertEquals('Closed Lost', staleOpen.StageName);
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleOpen.Description);
        System.assertEquals('Closed Lost', staleOpen2.StageName);
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleOpen2.Description);
        System.assertEquals('Closed Lost', staleNullStage.StageName);
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleNullStage.Description);

        // Everything else is left completely untouched.
        System.assertEquals('Prospecting', onCutoff.StageName);
        System.assertEquals(cutoff, onCutoff.CloseDate);
        System.assertEquals(null, onCutoff.Description);

        System.assertEquals('Prospecting', afterCutoff.StageName);
        System.assertEquals(cutoff + 30, afterCutoff.CloseDate);
        System.assertEquals(null, afterCutoff.Description);

        System.assertEquals('Closed Won', closedWon.StageName);
        System.assertEquals(cutoff - 1, closedWon.CloseDate);
        System.assertEquals(null, closedWon.Description);

        System.assertEquals('Closed Lost', closedLost.StageName);
        System.assertEquals(cutoff - 1, closedLost.CloseDate);
        System.assertEquals(null, closedLost.Description);

        System.assertEquals('Prospecting', nullCloseDate.StageName);
        System.assertEquals(null, nullCloseDate.CloseDate);
        System.assertEquals(null, nullCloseDate.Description);

        // Only the stale opportunities are registered dirty, each exactly once.
        mocks.verify(uowMock, mocks.times(1)).registerDirty(staleOpen);
        mocks.verify(uowMock, mocks.times(1)).registerDirty(staleOpen2);
        mocks.verify(uowMock, mocks.times(1)).registerDirty(staleNullStage);
        mocks.verify(uowMock, mocks.never()).registerDirty(onCutoff);
        mocks.verify(uowMock, mocks.never()).registerDirty(afterCutoff);
        mocks.verify(uowMock, mocks.never()).registerDirty(closedWon);
        mocks.verify(uowMock, mocks.never()).registerDirty(closedLost);
        mocks.verify(uowMock, mocks.never()).registerDirty(nullCloseDate);

        // Work is committed exactly once because at least one opportunity was closed.
        mocks.verify(uowMock, mocks.times(1)).commitWork();
    }

    @IsTest
    static void doesNotCloseAnythingNorCommitWorkWhenNothingIsStale() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
