/**
 * Publishes one Deal_Stage_Change__e platform event per Opportunity.
 *
 * Called from the Opportunity trigger handler (after insert / after update),
 * so Opportunity.Id is guaranteed to be populated and records arrive in
 * batches of up to 200.
 *
 * The platform events are "publish after commit", meaning they are only
 * delivered to subscribers if the current transaction commits successfully;
 * a failed SaveResult here indicates a validation/publish error for that
 * single event, not a transaction rollback.
 */
public inherited sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per Opportunity and returns
     * the SaveResults in the same order as the input list.
     *
     * @param opportunities Opportunities whose stage changes should be
     *                      published. May be null or empty; in that case
     *                      nothing is published and an empty list is returned.
     * @return One Database.SaveResult per input Opportunity, in input order.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Nothing to publish: short-circuit to avoid calling EventBus.publish
        // with nothing, and to guarantee an empty (never null) return value.
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e evt = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,      // 18-char case-safe Id
                Stage__c         = opp.StageName,
                Amount__c        = opp.Amount
            );

            // Publish one event at a time so that each SaveResult in the
            // returned list maps exactly to the Opportunity at the same
            // index, letting callers identify precisely which event failed.
            results.add(EventBus.publish(evt));
        }

        return results;
    }
}
