import ADD_TO_FAVORITES from '@salesforce/label/c.Favorite_Add';
import REMOVE_FROM_FAVORITES from '@salesforce/label/c.Favorite_Remove';

const ICON_FAVORITE = 'utility:favorite';
const ICON_NOT_FAVORITE = 'utility:favorite_disabled';

/**
 * Icon-style toggle button that marks a record as a favorite.
 * The parent owns the record state and passes it via `favorite`;
 * whenever the parent updates it, this component re-renders with the new value.
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favorite.
     * Reactive: any change made by the parent is reflected immediately.
     */
    @api favorite = false;

    /**
     * Label of the action a click will perform:
     * Remove when it is already a favorite, Add when it is not.
     */
    get actionLabel() {
        return this.favorite ? REMOVE_FROM_FAVORITES : ADD_TO_FAVORITES;
    }

    /**
     * aria-pressed state of the toggle button.
     * Returned as a string so the attribute is always rendered
     * explicitly as "true" or "false".
     */
    get isPressed() {
        return this.favorite ? 'true' : 'false';
    }

    /** Icon reflects the current toggle state. */
    get iconName() {
        return this.favorite ? ICON_FAVORITE : ICON_NOT_FAVORITE;
    }

    /**
     * Optimistic UI: flip the visible state immediately, then notify
     * the parent with the new boolean value.
     */
    handleClick() {
        this.favorite = !this.favorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this.favorite }
            })
        );
    }
}
