import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        this[event.target.dataset.field] = event.detail.value;
    }

    handleRegister() {
        const inputs = Array.from(
            this.template.querySelectorAll('lightning-input[data-field]')
        );
        const emailInput = inputs.find(
            (input) => input.dataset.field === 'email'
        );

        // Step 1: work-email validation via custom validity.
        const domain = this.email.trim().toLowerCase().split('@').pop();
        if (BLOCKED_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input so all messages show at once.
        let allValid = true;
        for (const input of inputs) {
            input.reportValidity();
            if (!input.checkValidity()) {
                allValid = false;
            }
        }

        // Step 3: stop if anything is invalid.
        if (!allValid) {
            return;
        }

        // Step 4: call Apex imperatively and toast the result.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
