        // aria-activedescendant references ids in the document, so make them
        // unique across every instance of this component.
        this._idBase = `status-listbox-option-${idCounter}`;
    }

    @api label;

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncActiveOption();
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        this._syncActiveOption();
    }

    /**
     * Id of the currently active (focus-referenced) option.
     * Null when there are no options (attribute is omitted).
     */
    get activeDescendantId() {
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            return null;
        }
        return `${this._idBase}-${this._activeIndex}`;
    }

    /**
     * View model for the rendered options.
     */
    get viewOptions() {
        const selectedValue = this._value;
        return this._options.map((option, index) => ({
            index,
            id: `${this._idBase}-${index}`,
            value: option.value,
            label: option.label,
            ariaSelected: option.value === selectedValue ? 'true' : 'false',
        }));
    }

    /**
     * The active option follows the selection: the selected option if the
     * current value exists in the options, otherwise the first option.
     */
    _syncActiveOption() {
        const index = this._options.findIndex(
            (option) => option.value === this._value
        );
        this._activeIndex = index >= 0 ? index : 0;
    }

    handleKeyDown(event) {
        const key = event.key;
        let handled = true;

        switch (key) {
            case 'ArrowDown':
                this._moveActive(this._activeIndex + 1);
                break;
            case 'ArrowUp':
                this._moveActive(this._activeIndex - 1);
                break;
            case 'Home':
                this._moveActive(0);
                break;
            case 'End':
                this._moveActive(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                if (this._options.length > 0) {
                    this._select(this._activeIndex);
                }
                break;
            default:
                handled = false;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleClick(event) {
        const option = event.target.closest('li[role="option"]');
        if (!option) {
            return;
        }
        const index = Number(option.dataset.index);
        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }
        // Clicking makes the option active and selects it.
        this._activeIndex = index;
        this._select(index);
    }

    _moveActive(index) {
        if (this._options.length === 0) {
            return;
        }
        // Clamp, so the active option stops at the first/last option
        // (no wrap-around).
        this._activeIndex = Math.max(0, Math.min(index, this._options.length - 1));
    }

    _select(index) {
        const value = this._options[index].value;
        if (value === this._value) {
            // Already selected: nothing changes, nothing is dispatched.
            return;
        }
        this._value = value;
        this._activeIndex = index;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value } })
        );
    }
}
