```apex
/**
 * Service that records monthly giving sign-ups coming from the nonprofit's
 * donation form as Enhanced Recurring Donations (NPSP).
 *
 * NPSP itself generates the installment Opportunities; this service only
 * creates the Recurring Donation records and lets the NPSP triggers do the rest.
 *
 * Governor-limit safe: for up to 200 requests in one call this service uses
 * 0 SOQL statements of its own and exactly 1 DML statement (a single bulk insert).
 */
public with sharing class RecurringGiftService {

    /** Custom exception used for all validation and processing failures. */
    public class RecurringGiftException extends Exception {}

    /** Input describing one monthly gift sign-up from the donation form. */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31; 31 means "last day of the month"
        public Date startDate;
        public Integer installments;  // null or 0 = no end date (open-ended)
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String STATUS_ACTIVE = 'Active';
    private static final Integer LAST_DAY_OF_MONTH = 31;
    private static final Integer MONTHLY_FREQUENCY = 1;

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests the gift sign-ups to record.
     * @return the Ids of the created Recurring Donations, in request order.
     * @throws RecurringGiftException if any request is invalid (thrown before
     *         any DML occurs), or if the insert fails.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> createdIds = new List<Id>();

        // A null or empty list is a no-op.
        if (requests == null || requests.isEmpty()) {
            return createdIds;
        }

        // ------------------------------------------------------------------
        // Validate every request up front so that we never perform partial
        // DML: either every record is valid and gets inserted together, or
        // nothing is inserted at all.
        // ------------------------------------------------------------------
        List<String> validationErrors = new List<String>();
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];

            if (req == null) {
                validationErrors.add(
                    'Request ' + i + ': the request itself is null.');
                continue;
            }

            if (req.contactId == null) {
                validationErrors.add(
                    'Request ' + i + ': contactId is required.');
            }

            if (req.amount == null || req.amount <= 0) {
                validationErrors.add(
                    'Request ' + i + ': amount must be a positive number.');
            }

            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                validationErrors.add(
                    'Request ' + i + ': dayOfMonth must be between 1 and 31.');
            }

            if (req.startDate == null) {
                validationErrors.add(
                    'Request ' + i + ': startDate is required.');
            }
        }

        if (!validationErrors.isEmpty()) {
            throw new RecurringGiftException(
                'Invalid gift request(s): ' + String.join(validationErrors, ' '));
        }

        // ------------------------------------------------------------------
        // Build all the Recurring Donations. One DML statement handles the
        // entire batch, regardless of how many requests there are.
        // ------------------------------------------------------------------
        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            // null or 0 (or a non-positive value) means an open-ended
            // recurring donation; anything positive is a fixed-length one.
            Boolean isOpenEnded = (req.installments == null || req.installments <= 0);

            // The form's "31" means "last day of the month". Enhanced
            // Recurring Donations has a dedicated option for that, so we set
            // it instead of relying on day 31 alone. 29 and 30 are stored
            // as those literal days.
            Boolean alwaysUseLastDayOfMonth = (req.dayOfMonth == LAST_DAY_OF_MONTH);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                // Donor and gift details.
                npe03__Contact__c                     = req.contactId,
                npe03__Amount__c                      = req.amount,
                npe03__PaymentMethod__c               = null, // payment method lives on the ERD field below

                // Classic schedule fields kept in sync for reporting.
                npe03__Installment_Period__c          = INSTALLMENT_PERIOD_MONTHLY,
                npe03__Date_Established__c            = req.startDate,
                npe03__Schedule_Type__c               = isOpenEnded ? RECURRING_TYPE_OPEN : RECURRING_TYPE_FIXED,

                // Enhanced Recurring Donations schedule: every month on the
                // requested day, starting on startDate. NPSP derives the
                // first/next payment dates and generates the installment
                // Opportunities from this schedule.
                npsp__RecurringType__c                = isOpenEnded ? RECURRING_TYPE_OPEN : RECURRING_TYPE_FIXED,
                npsp__StartDate__c                    = req.startDate,
                npsp__InstallmentFrequency__c         = MONTHLY_FREQUENCY,
                npsp__Day_of_Month__c                 = req.dayOfMonth,
                npsp__Always_Use_Last_Day_Of_Month__c = alwaysUseLastDayOfMonth,
                npsp__Status__c                       = STATUS_ACTIVE,
                npsp__PaymentMethod__c                = req.paymentMethod
            );

            if (isOpenEnded) {
                // Open-ended: no planned installment count and no end date;
                // the open-ended status keeps the record Active until NPSP
                // closes it.
                rd.npe03__Installments__c = null;
                rd.npe03__Open_Ended_Status__c = STATUS_ACTIVE;
                rd.npsp__EndDate__c = null;
            } else {
                // Fixed-length: the number of planned installments. NPSP
                // computes the end date and generates exactly this many
                // installment Opportunities.
                rd.npe03__Installments__c = req.installments;
                rd.npe03__Open_Ended_Status__c = null;
            }

            donations.add(rd);
        }

        // ------------------------------------------------------------------
        // Single bulk DML statement. Order is preserved, so the Ids come
        // back in the same order as the requests.
        // ------------------------------------------------------------------
        try {
            insert donations;
        } catch (DmlException e) {
            throw new RecurringGiftException(
                'Failed to create the recurring donations: ' + e.getMessage(), e);
        }

        for (npe03__Recurring_Donation__c rd : donations) {
            createdIds.add(rd.Id);
        }

        return createdIds;
    }
}
